const query = $input.item.json.query;
if (query && query['hub.verify_token'] === 'CLIXA_SECRET_TOKEN_2026') {
  return [{ json: { text: query['hub.challenge'] } }];
}
return [{ json: { text: 'Forbidden' } }];

const body = $input.item.json.body || {};
let from = '';
let messageText = '';

try {
  if (body.entry && body.entry[0]?.changes[0]?.value?.messages) {
    const msg = body.entry[0].changes[0].value.messages[0];
    from = msg.from;
    messageText = msg.text?.body || '';
  }
} catch (e) {}

// Détection réservation automatique provenant du site web CLIXA
const isWebBooking = messageText.includes('📅 Date souhaitée') && messageText.includes('⏰ Créneau horaire');

let appointment = null;
if (isWebBooking) {
  const dayMatch = messageText.match(/📅 Date souhaitée\s*:\s*(.+)/i);
  const timeMatch = messageText.match(/⏰ Créneau horaire\s*:\s*(.+)/i);
  const topicMatch = messageText.match(/💼 Thématique\s*:\s*(.+)/i);
  const nameMatch = messageText.match(/👤 Nom & Prénom\s*:\s*(.+)/i);
  const companyMatch = messageText.match(/🏢 Entreprise\s*:\s*(.+)/i);
  const phoneMatch = messageText.match(/📞 Mon numéro\s*:\s*(.+)/i);

  appointment = {
    day: dayMatch ? dayMatch[1].trim() : 'Demain',
    time: timeMatch ? timeMatch[1].trim() : '11:00',
    topic: topicMatch ? topicMatch[1].trim() : 'Conseil & ERP',
    name: nameMatch ? nameMatch[1].trim() : 'Client CLIXA',
    company: companyMatch ? companyMatch[1].trim() : 'Non renseigné',
    phone: phoneMatch ? phoneMatch[1].trim() : from
  };
}

return [{
  json: {
    from,
    messageText,
    isWebBooking,
    appointment,
    adminPhone: '00212661344054'
  }
}];

